export function SearchSuggestion({
  label = "{{label}}",
  query = "{{query}}",
  highlighted = "{{highlighted}}",
  accent = "{{accent}}",
}) {
  const options = [
    { id: "graphs", text: "Graphs & charts" },
    { id: "grants", text: "Grants overview" },
    { id: "gradients", text: "Gradient presets" },
  ];
  return (
    <div style={{ display: "block", fontFamily: "system-ui, sans-serif", fontSize: 14, color: "#241430", maxWidth: 260, position: "relative" }}>
      <label htmlFor="ssug-input" style={{ display: "block", marginBottom: 6, fontWeight: 500 }}>{label}</label>
      <input id="ssug-input" type="search" role="combobox" aria-expanded="true" aria-controls="ssug-list" aria-activedescendant={`opt-${highlighted}`} defaultValue={query} style={{
        width: "100%", boxSizing: "border-box", padding: "9px 11px", font: "inherit", color: "#241430",
        background: "#FAF7F2", border: "1.5px solid #24143026", borderRadius: "8px 8px 0 0",
      }} />
      <ul id="ssug-list" role="listbox" style={{ listStyle: "none", margin: 0, padding: 4, background: "#FAF7F2", border: "1.5px solid #24143026", borderTop: "none", borderRadius: "0 0 8px 8px" }}>
        {options.map((opt) => (
          <li key={opt.id} id={`opt-${opt.id}`} role="option" aria-selected={opt.id === highlighted} style={{
            padding: "7px 8px", borderRadius: 6, cursor: "pointer",
            background: opt.id === highlighted ? accent : "transparent",
            fontWeight: opt.id === highlighted ? 600 : 400,
          }}>{opt.text}</li>
        ))}
      </ul>
    </div>
  );
}
